contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public payable {
        require(maker != address(0), "maker nonzero");
        require(expiration > block.timestamp, "not expired");
        require(duration < 10_000 days, "duration ok");

        C.Order memory order;
        order.maker = maker;
        order.isCall = true;
        order.isLong = false;
        order.baseAsset = c.weth();
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = expiration;
        order.nonce = nonce;
        order.whitelist = new address[](0);
        order.floorTokens = new address[](0);
        order.erc20Assets = new C.ERC20Asset[](0);
        order.erc721Assets = new C.ERC721Asset[](0);

        uint256[] memory noFloorIds = new uint256[](0);

        bytes32 orderHash = c.hashOrder(order);
        bytes32 positionId = c.hashOppositeOrder(order);

        uint256 beforeNativeBalance = address(c).balance;

        uint256 sent = premium;
        require(address(this).balance >= sent, "insufficient balance");

        c.fillOrder{value: sent}(order, "", noFloorIds);

        bool shortPositionMintedToSender = (c.ownerOf(uint256(positionId)) == address(this));
        bool longPositionMintedToMaker = (c.ownerOf(uint256(orderHash)) == maker);
        uint256 afterNativeBalance = address(c).balance;

        assert(shortPositionMintedToSender && longPositionMintedToMaker && afterNativeBalance == beforeNativeBalance);
    }

    receive() external payable {}
}

