contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] memory whitelist,
        address[] memory floorTokens,
        C.ERC20Asset[] memory erc20Assets,
        C.ERC721Asset[] memory erc721Assets,
        bytes calldata signature,
        uint256[] memory floorAssetTokenIds,
        uint256 value
    ) public payable {
        require(address(this).balance >= value);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256 positionId;
        bool reverted;
        try c.fillOrder{value: value}(order, signature, floorAssetTokenIds) returns (uint256 id) {
            positionId = id;
            reverted = false;
        } catch {
            reverted = true;
        }

        address owner1;
        address owner2;
        if (!reverted) {
            bytes32 oppositeHash = c.hashOppositeOrder(order);
            owner1 = c.ownerOf(positionId);
            owner2 = c.ownerOf(uint256(oppositeHash));
        }

        assert(reverted || (owner1 == address(this) && owner2 == address(this)));
    }

    receive() external payable {}
}

