contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] memory whitelist,
        address[] memory floorTokens,
        C.ERC20Asset[] memory erc20Assets,
        C.ERC721Asset[] memory erc721Assets,
        bytes calldata signature,
        uint256[] memory floorAssetTokenIds
    ) public payable {
        require(premium > 0, "premium must be positive");
        require(msg.value == 0, "no ETH");

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        (bool reverted, uint256 positionId) = _tryFill(order, signature, floorAssetTokenIds);
        if (!reverted) {
            assert(c.ownerOf(uint256(c.hashOrder(order))) == maker);
        }
    }

    function _tryFill(
        C.Order memory order,
        bytes calldata signature,
        uint256[] memory floorAssetTokenIds
    ) internal returns (bool reverted, uint256 positionId) {
        try c.fillOrder(order, signature, floorAssetTokenIds) returns (uint256 p) {
            return (false, p);
        } catch {
            return (true, 0);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] memory whitelist,
        address[] memory floorTokens,
        C.ERC20Asset[] memory erc20Assets,
        C.ERC721Asset[] memory erc721Assets
    ) public {
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        bool wasCancelled = c.cancelledOrders(orderHash);

        bool reverted;
        try c.cancel(order) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.cancelledOrders(orderHash));
        } else {
            assert(c.cancelledOrders(orderHash) == wasCancelled);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] memory whitelist,
        address[] memory floorTokens,
        C.ERC20Asset[] memory erc20Assets,
        C.ERC721Asset[] memory erc721Assets,
        bytes32 otherHash
    ) public {
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        bool otherWasCancelled = c.cancelledOrders(otherHash);
        bool orderWasCancelled = c.cancelledOrders(orderHash);

        bool reverted;
        try c.cancel(order) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            orderHash == otherHash
                ? c.cancelledOrders(orderHash) == (reverted ? orderWasCancelled : true)
                : c.cancelledOrders(orderHash) == (reverted ? orderWasCancelled : true)
                    && c.cancelledOrders(otherHash) == otherWasCancelled
        );
    }

    receive() external payable {}
}

