contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public {
        require(maker != address(0), "maker zero");
        require(baseAsset.code.length > 0, "baseAsset not contract");
        require(duration < 10_000 days, "duration too long");

        C.Order memory order;
        order.maker = maker;
        order.isCall = isCall;
        order.isLong = isLong;
        order.baseAsset = baseAsset;
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = expiration;
