        order.erc721Assets = new C.ERC721Asset[](0);

        bytes32 orderHash = c.hashOrder(order);
        require(!c.cancelledOrders(orderHash), "cancelled before cancel");

        c.cancel(order);

        bool cancelledAfter = c.cancelledOrders(orderHash);

        bytes memory signature = new bytes(0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);
        bool fillReverted;
        try c.fillOrder(order, signature, floorAssetTokenIds) {
            fillReverted = false;
        } catch {
            fillReverted = true;
        }

        assert(cancelledAfter && fillReverted);
    }

