contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] memory whitelist,
        address[] memory floorTokens,
        C.ERC20Asset[] memory erc20Assets,
        C.ERC721Asset[] memory erc721Assets,
        uint256[] memory floorAssetTokenIds,
        uint256 premiumPaid
    ) public payable {
        require(maker != address(0), "maker zero");
        require(baseAsset != address(0), "baseAsset zero");
        require(expiration > block.timestamp, "expiration not future");
        require(duration < 10_000 days, "duration too long");
        require(whitelist.length == 0, "whitelist not empty");
        require(erc20Assets.length == 0, "erc20Assets not empty");
        require(erc721Assets.length == 0, "erc721Assets not empty");
        require(!isCall || !isLong || floorAssetTokenIds.length == floorTokens.length, "floor ids length mismatch");
        require(isCall && isLong || floorAssetTokenIds.length == 0, "unexpected floor ids");
        require(isLong || msg.value == 0 || premiumPaid == msg.value, "wrong native amount");
        if (!isLong) {
            require(msg.value == 0 || address(this).balance >= premiumPaid, "insufficient balance");
        }

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bool filled;
        uint256 positionId;
        try c.fillOrder(order, new bytes(65), floorAssetTokenIds) returns (uint256 id) {
            positionId = id;
            filled = true;
        } catch {
            filled = false;
        }

        if (filled) {
            bytes32 orderHash = c.hashOrder(order);
            bytes32 oppositeHash = c.hashOppositeOrder(order);
            assert(
                c.ownerOf(uint256(orderHash)) == maker &&
                c.ownerOf(uint256(oppositeHash)) == address(this) &&
                positionId == uint256(oppositeHash)
            );
        }
    }

    receive() external payable {}
}

